class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        best = {}
        for i in range(1, len(nums) + 1):
            x, d = i, 2
            while d * d <= x:
                while x % (d * d) == 0:
                    x //= d * d
                d += 1
            best[x] = best.get(x, 0) + nums[i - 1]
        return max(best.values())

