class Solution {
public:
    long long maximumSum(vector<int>& nums) {
        unordered_map<int, long long> best;
        long long ans = 0;
        int n = nums.size();
        for (int i = 1; i <= n; i++) {
            int x = i;
            for (int d = 2; (long long)d * d <= x; d++)
                while (x % (d * d) == 0) x /= d * d;
            ans = max(ans, best[x] += nums[i - 1]);
        }
        return ans;
    }
};

