class Solution {
    public long maximumSum(int[] nums) {
        Map<Integer, Long> best = new HashMap<>();
        long ans = 0;
        int n = nums.length;
        for (int i = 1; i <= n; i++) {
            int x = i;
            for (int d = 2; (long) d * d <= x; d++)
                while (x % (d * d) == 0) x /= d * d;
            long v = best.merge(x, (long) nums[i - 1], Long::sum);
            ans = Math.max(ans, v);
        }
        return ans;
    }
}

