class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        n = len(nums)
        has_square = [False] * (n + 1)
        d = 2
        while d * d <= n:
            for m in range(d * d, n + 1, d * d):
                has_square[m] = True
            d += 1
        ans = 0
        for r in range(1, n + 1):
            if has_square[r]:
                continue
            s = 0
            cur = r
            while cur <= n:
                s += nums[cur - 1]
                cur += 2 * r * (cur // r) - r  # advance by next square multiple
            ans = max(ans, s)
        return ans

