class Solution {
public:
    long long maximumSum(vector<int>& nums) {
        int n = nums.size();
        vector<bool> hasSquare(n + 1, false);
        for (int d = 2; (long long)d * d <= n; d++)
            for (int m = d * d; m <= n; m += d * d) hasSquare[m] = true;
        long long ans = 0;
        for (int r = 1; r <= n; r++) {
            if (hasSquare[r]) continue;
            long long s = 0;
            for (int t = 1; (long long)r * t * t <= n; t++)
                s += nums[r * t * t - 1];
            ans = max(ans, s);
        }
        return ans;
    }
};

